mapper.select:
select
sba.user_name,su.user_id,su.description,sba.role_code,srvl.role_name,srvl.role_id,sba.button_authority_id,sba.start_date,sba.end_date
from SYS_BUTTON_AUTHORITY sba
left join sys_role_b srvl
on sba.role_code = srvl.role_code
left join sys_user su
on sba.user_name = su.user_name


        sba.role_code = #{roleCode}


        and sba.user_name = #{userName}


        and su.description = #{description}


        and srvl.role_name = #{roleName}


order by
BUTTON_AUTHORITY_ID
